mapper.update:
UPDATE access_requests
SET status = #{newStatus},
reviewed_by = #{reviewerId},
reviewed_at = CURRENT_TIMESTAMP,
reject_reason = #{rejectReason},
updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
AND status = #{currentStatus}
AND user_id != #{reviewerId}

mapper.select:
SELECT id, user_id, facility_id, status, request_reason, access_start_at, access_end_at, reviewed_by, reviewed_at, reject_reason, created_at, updated_at FROM access_requests
AND user_id = #{userId}
AND facility_id = #{facilityId}
AND status = #{status}
AND created_at >= #{from}
AND created_at <= #{to}
ORDER BY created_at DESC
